const PHOTO_BANK=[{"image": "photos/PIA24434.jpg", "year": 1903, "title": "A first flight", "alt": "A fragile aircraft lifts off above a sandy field.", "story": "At Kitty Hawk, Orville Wright flew for 12 seconds on December 17, 1903. Wilbur ran alongside.", "credit": "John T. Daniels / Library of Congress, via NASA", "source": "https://images.nasa.gov/details/PIA24434"}, {"image": "photos/as11-40-5903.jpg", "year": 1969, "title": "Footprints on the Moon", "alt": "A spacesuited astronaut stands on a rocky surface.", "story": "Neil Armstrong photographed Buzz Aldrin during the Apollo 11 moonwalk on July 20, 1969.", "credit": "NASA / Neil Armstrong", "source": "https://images.nasa.gov/details/as11-40-5903"}, {"image": "photos/s81-30462.jpg", "year": 1981, "title": "A new kind of spacecraft", "alt": "A winged spacecraft launches beside a service tower.", "story": "Columbia launched on April 12, 1981, carrying John Young and Robert Crippen on the first Space Shuttle mission.", "credit": "NASA", "source": "https://images.nasa.gov/details/s81-30462"}, {"image": "photos/s31-10-023.jpg", "year": 1990, "title": "A telescope leaves home", "alt": "A large cylindrical instrument is held above Earth by a robotic arm.", "story": "Discovery carried the Hubble Space Telescope into orbit. This view was photographed on April 25, 1990, during deployment preparations.", "credit": "NASA", "source": "https://images.nasa.gov/details/s31-10-023"}, {"image": "photos/s75-29432.jpg", "year": 1975, "title": "A handshake above Earth", "alt": "Two space travellers greet each other inside a spacecraft.", "story": "Thomas Stafford and Alexei Leonov shook hands on July 17, 1975, during the joint Apollo\u2013Soyuz mission. This image is a frame from motion-picture film.", "credit": "NASA", "source": "https://images.nasa.gov/details/s75-29432"}, {"image": "photos/S85-41007.jpg", "year": 1983, "title": "Preparing for a milestone", "alt": "An astronaut in training rests with a helmet.", "story": "NASA identifies the photograph as May 9, 1983: Sally Ride preparing for STS-7. She became the first American woman in space that June.", "credit": "NASA", "source": "https://images.nasa.gov/details/S85-41007"}, {"image": "photos/india-salt.jpg", "year": 1930, "title": "A march that changed history", "alt": "People in simple clothing walk together on a dusty road.", "story": "Gandhi and fellow marchers during the Salt March in March\u2013April 1930. The protest challenged British control over salt.", "credit": "Unknown photographer / Wikimedia Commons \u00b7 public domain", "source": "https://commons.wikimedia.org/wiki/File:Gandhi_Salt_March.jpg", "india": true}, {"image": "photos/india-flag.jpg", "year": 1947, "title": "A new flag for a new chapter", "alt": "A man in a white cap holds up a flag with a wheel at its centre.", "story": "This news photograph shows Jawaharlal Nehru presenting the new Indian flag in July 1947, shortly before independence.", "credit": "Unknown news photographer / Wikimedia Commons \u00b7 public domain in India", "source": "https://commons.wikimedia.org/wiki/File:A_news_bureau_photo_of_Nehru_and_the_new_flag.jpg", "india": true}, {"image": "photos/india-delhi.jpg", "year": 1911, "title": "A grand gathering in Delhi", "alt": "A ceremonial canopy overlooks a vast gathering in an open field.", "story": "The Delhi Durbar on 12 December 1911, with King George V and Queen Mary on the dais, during British rule in India.", "credit": "Unknown photographer / Wikimedia Commons \u00b7 public domain", "source": "https://commons.wikimedia.org/wiki/File:Delhi_Durbar,_1911.jpg", "india": true}];
